mapper.select:
SELECT s.id, s.user_id, u.nickname AS author_name, u.avatar AS author_avatar, s.title, s.cover_image, s.summary, s.destination, s.days, s.budget, s.season, s.tags, s.view_count, s.like_count, s.favorite_count, s.comment_count, s.is_ai_generated, s.audit_status, s.root_strategy_id, s.create_time, CASE WHEN l.id IS NOT NULL THEN 1 ELSE 0 END AS is_liked, CASE WHEN f.id IS NOT NULL THEN 1 ELSE 0 END AS is_favorited FROM strategy s LEFT JOIN user u ON s.user_id = u.id LEFT JOIN favorite l ON s.id = l.item_id AND l.item_type = 'strategy_like' AND l.user_id = #{userId} LEFT JOIN favorite f ON s.id = f.item_id AND f.item_type = 'strategy' AND f.user_id = #{userId} WHERE s.deleted = 0 AND s.audit_status = 1 AND s.status = 1 AND s.visibility = 1
AND s.destination LIKE CONCAT('%', #{destination}, '%')
AND (s.title LIKE CONCAT('%', #{keyword}, '%') OR s.content LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%'))
AND JSON_CONTAINS(s.tags, CONCAT('"', #{tag}, '"'))
AND s.budget >= #{minBudget}
AND s.budget <= #{maxBudget}
AND s.days >= #{minDays}
AND s.days <= #{maxDays}
AND (s.season = #{season} OR s.season = 'all')
ORDER BY s.like_count DESC, s.view_count DESC
ORDER BY s.favorite_count DESC
ORDER BY s.create_time DESC

SELECT s.id, s.title, s.cover_image, s.destination, s.days, s.budget, s.view_count, s.like_count, s.tags, u.nickname AS author_name, s.create_time FROM strategy s LEFT JOIN user u ON s.user_id = u.id WHERE s.deleted = 0 AND s.audit_status = 1 AND s.status = 1 AND s.visibility = 1 AND s.id != #{id} AND (s.destination = #{destination}
OR JSON_OVERLAPS(s.tags, #{tags})
) ORDER BY s.like_count DESC LIMIT #{limit}
